CREATE TABLE IF NOT EXISTS "components" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Parent component, making the tree. Null at the top level. One level of grouping covers almost every real page, but the self-reference costs nothing and avoids a rewrite when a region tier appears.
	"parent_id" BIGINT,
	-- Stable identifier in the public URL and in the API. Renaming the display name must never break a bookmark or an integration.
	"slug" VARCHAR(64) NOT NULL UNIQUE,
	-- Display name, e.g. API or Dashboard. Written for customers, not for the org chart — components people cannot recognise make a status page useless.
	"name" VARCHAR(120) NOT NULL,
	-- One line explaining what it covers, which is how you avoid five tickets asking whether webhooks are part of API.
	"description" VARCHAR(400),
	-- True for a container that has no status of its own and rolls up its children. A group with an independently set status is the fastest way to publish a contradiction.
	"is_group" BOOLEAN NOT NULL DEFAULT false,
	-- Position among siblings. Explicit, because the order on a status page is an editorial decision — most-asked-about first — not alphabetical.
	"display_order" SMALLINT NOT NULL DEFAULT 0,
	-- operational | degraded_performance | partial_outage | major_outage | under_maintenance. A cached value: the public page reads it on every request and must never compute it from history.
	"current_status" VARCHAR(24) NOT NULL DEFAULT 'operational',
	-- When the current status was set. Drives the how long has this been broken line that every visitor looks for first.
	"status_changed_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- False for internal components shown only on a private page, which is how one system serves both audiences without two deployments.
	"is_public" BOOLEAN NOT NULL DEFAULT true,
	-- Whether the uptime bar is published for this component. Some components are real but have no honest uptime measurement, and showing a fabricated one is worse than showing none.
	"show_uptime" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "components" IS 'What customers see and subscribe to. The hierarchy exists so a regional outage can be reported precisely without the top-level page claiming everything is down.';
COMMENT ON COLUMN "components"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "components"."parent_id" IS 'Parent component, making the tree. Null at the top level. One level of grouping covers almost every real page, but the self-reference costs nothing and avoids a rewrite when a region tier appears.';
COMMENT ON COLUMN "components"."slug" IS 'Stable identifier in the public URL and in the API. Renaming the display name must never break a bookmark or an integration.';
COMMENT ON COLUMN "components"."name" IS 'Display name, e.g. API or Dashboard. Written for customers, not for the org chart — components people cannot recognise make a status page useless.';
COMMENT ON COLUMN "components"."description" IS 'One line explaining what it covers, which is how you avoid five tickets asking whether webhooks are part of API.';
COMMENT ON COLUMN "components"."is_group" IS 'True for a container that has no status of its own and rolls up its children. A group with an independently set status is the fastest way to publish a contradiction.';
COMMENT ON COLUMN "components"."display_order" IS 'Position among siblings. Explicit, because the order on a status page is an editorial decision — most-asked-about first — not alphabetical.';
COMMENT ON COLUMN "components"."current_status" IS 'operational | degraded_performance | partial_outage | major_outage | under_maintenance. A cached value: the public page reads it on every request and must never compute it from history.';
COMMENT ON COLUMN "components"."status_changed_at" IS 'When the current status was set. Drives the how long has this been broken line that every visitor looks for first.';
COMMENT ON COLUMN "components"."is_public" IS 'False for internal components shown only on a private page, which is how one system serves both audiences without two deployments.';
COMMENT ON COLUMN "components"."show_uptime" IS 'Whether the uptime bar is published for this component. Some components are real but have no honest uptime measurement, and showing a fabricated one is worse than showing none.';

CREATE INDEX "idx_components_parent_order"
ON "components" ("parent_id", "display_order");

CREATE TABLE IF NOT EXISTS "component_status_history" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Component whose status changed.
	"component_id" BIGINT NOT NULL,
	-- operational | degraded_performance | partial_outage | major_outage | under_maintenance. The status held during this interval.
	"status" VARCHAR(24) NOT NULL,
	-- When the component entered this status. Intervals are contiguous: the previous row ends exactly here.
	"started_at" TIMESTAMPTZ NOT NULL,
	-- When it left. Null for the current status, which makes the open interval a single indexed lookup.
	"ended_at" TIMESTAMPTZ,
	-- manual | incident | maintenance | automated_check. Provenance decides whether the interval counts against uptime, and a maintenance interval usually does not.
	"cause" VARCHAR(24) NOT NULL DEFAULT 'manual',
	-- Incident that caused it, when one did. Null for a manual change or an automated detection with no incident opened yet.
	"incident_id" BIGINT,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "component_status_history" IS 'Append-only intervals of component state. This, not the incident list, is what uptime is computed from — an incident is a story told about a period, and the period is the fact.';
COMMENT ON COLUMN "component_status_history"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "component_status_history"."component_id" IS 'Component whose status changed.';
COMMENT ON COLUMN "component_status_history"."status" IS 'operational | degraded_performance | partial_outage | major_outage | under_maintenance. The status held during this interval.';
COMMENT ON COLUMN "component_status_history"."started_at" IS 'When the component entered this status. Intervals are contiguous: the previous row ends exactly here.';
COMMENT ON COLUMN "component_status_history"."ended_at" IS 'When it left. Null for the current status, which makes the open interval a single indexed lookup.';
COMMENT ON COLUMN "component_status_history"."cause" IS 'manual | incident | maintenance | automated_check. Provenance decides whether the interval counts against uptime, and a maintenance interval usually does not.';
COMMENT ON COLUMN "component_status_history"."incident_id" IS 'Incident that caused it, when one did. Null for a manual change or an automated detection with no incident opened yet.';

CREATE INDEX "idx_status_history_component_start"
ON "component_status_history" ("component_id", "started_at");
CREATE INDEX "idx_status_history_open"
ON "component_status_history" ("ended_at");

CREATE TABLE IF NOT EXISTS "incidents" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Public URL segment, stable for as long as the incident page is linked to from anywhere.
	"slug" VARCHAR(80) NOT NULL UNIQUE,
	-- Headline in plain language. Written for a customer who does not know your architecture, which is the hardest part of running a status page.
	"title" VARCHAR(200) NOT NULL,
	-- minor | major | critical. Set at declaration and revised as understanding improves, so the field records the current assessment rather than the first guess.
	"severity" VARCHAR(16) NOT NULL DEFAULT 'minor',
	-- investigating | identified | monitoring | resolved. The four states are a promise about what the next update will contain, which is why the vocabulary is fixed.
	"status" VARCHAR(16) NOT NULL DEFAULT 'investigating',
	-- monitoring | customer_report | internal_report. The ratio of customer to monitoring detection is the honest measure of observability.
	"detected_by" VARCHAR(24) NOT NULL DEFAULT 'monitoring',
	-- When impact began, which is usually earlier than when the incident was declared. Backdating this is normal and is what keeps time-to-detect measurable.
	"started_at" TIMESTAMPTZ NOT NULL,
	-- When the incident was opened on the page. Gap from started_at is time to detect and announce.
	"declared_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- When impact ended. Null while open, and the gap from started_at is the duration customers experienced, not the duration engineers worked.
	"resolved_at" TIMESTAMPTZ,
	-- False for an incident tracked internally that was never published. Publishing after the fact is a decision, and the row must exist before it is made.
	"is_public" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "incidents" IS 'An unplanned disruption. It carries the narrative and the timing; which components were affected and how badly lives on the join, because impact varies by component and changes during the incident.';
COMMENT ON COLUMN "incidents"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "incidents"."slug" IS 'Public URL segment, stable for as long as the incident page is linked to from anywhere.';
COMMENT ON COLUMN "incidents"."title" IS 'Headline in plain language. Written for a customer who does not know your architecture, which is the hardest part of running a status page.';
COMMENT ON COLUMN "incidents"."severity" IS 'minor | major | critical. Set at declaration and revised as understanding improves, so the field records the current assessment rather than the first guess.';
COMMENT ON COLUMN "incidents"."status" IS 'investigating | identified | monitoring | resolved. The four states are a promise about what the next update will contain, which is why the vocabulary is fixed.';
COMMENT ON COLUMN "incidents"."detected_by" IS 'monitoring | customer_report | internal_report. The ratio of customer to monitoring detection is the honest measure of observability.';
COMMENT ON COLUMN "incidents"."started_at" IS 'When impact began, which is usually earlier than when the incident was declared. Backdating this is normal and is what keeps time-to-detect measurable.';
COMMENT ON COLUMN "incidents"."declared_at" IS 'When the incident was opened on the page. Gap from started_at is time to detect and announce.';
COMMENT ON COLUMN "incidents"."resolved_at" IS 'When impact ended. Null while open, and the gap from started_at is the duration customers experienced, not the duration engineers worked.';
COMMENT ON COLUMN "incidents"."is_public" IS 'False for an incident tracked internally that was never published. Publishing after the fact is a decision, and the row must exist before it is made.';

CREATE INDEX "idx_incidents_status_started"
ON "incidents" ("status", "started_at");
CREATE INDEX "idx_incidents_started"
ON "incidents" ("started_at");

CREATE TABLE IF NOT EXISTS "incident_components" (
	-- Incident affecting the component. Half of the composite key.
	"incident_id" BIGINT,
	-- Component affected. Half of the composite key.
	"component_id" BIGINT,
	-- degraded_performance | partial_outage | major_outage. Per component, because one incident often means a full outage in one region and slowness everywhere else.
	"impact_status" VARCHAR(24) NOT NULL DEFAULT 'degraded_performance',
	-- When this component was attached to the incident. Components are added as an investigation widens, and the page should show when the scope grew.
	"added_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("incident_id", "component_id")
);

COMMENT ON TABLE "incident_components" IS 'Scope of an incident. The many-to-many is unavoidable: one incident hits several components, and one component accumulates many incidents over its life.';
COMMENT ON COLUMN "incident_components"."incident_id" IS 'Incident affecting the component. Half of the composite key.';
COMMENT ON COLUMN "incident_components"."component_id" IS 'Component affected. Half of the composite key.';
COMMENT ON COLUMN "incident_components"."impact_status" IS 'degraded_performance | partial_outage | major_outage. Per component, because one incident often means a full outage in one region and slowness everywhere else.';
COMMENT ON COLUMN "incident_components"."added_at" IS 'When this component was attached to the incident. Components are added as an investigation widens, and the page should show when the scope grew.';

CREATE INDEX "idx_incident_components_component"
ON "incident_components" ("component_id");

CREATE TABLE IF NOT EXISTS "scheduled_maintenances" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Public URL segment.
	"slug" VARCHAR(80) NOT NULL UNIQUE,
	-- What is being done, in customer terms.
	"title" VARCHAR(200) NOT NULL,
	-- Expected impact in detail, published when the window is announced rather than when it starts.
	"description" TEXT,
	-- scheduled | in_progress | completed | cancelled. Cancelled windows stay as rows because subscribers were already notified and are owed the retraction.
	"status" VARCHAR(16) NOT NULL DEFAULT 'scheduled',
	-- Announced start. Subscribers are notified relative to this, so moving it is a communication event, not an edit.
	"scheduled_start_at" TIMESTAMPTZ NOT NULL,
	-- Announced end. Customers plan around this number more than any other on the page.
	"scheduled_end_at" TIMESTAMPTZ NOT NULL,
	-- When work really began. Null until it does.
	"actual_start_at" TIMESTAMPTZ,
	-- When it really finished. Overrunning a window is the complaint maintenance generates, and it is only visible if planned and actual are both kept.
	"actual_end_at" TIMESTAMPTZ,
	-- Lead time for the reminder notification. Per window, because a five-minute restart and a four-hour migration deserve different warning.
	"notify_hours_before" SMALLINT NOT NULL DEFAULT 24,
	-- Whether status moves on the schedule without a human. Convenient and dangerous: an automatic completion while work is still running publishes a lie.
	"auto_transition" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "scheduled_maintenances" IS 'Planned work, kept apart from incidents because it is announced before it happens, notified on a lead time, and generally excluded from uptime. Everything else about it — the timeline, the subscribers, the components — reuses the incident machinery.';
COMMENT ON COLUMN "scheduled_maintenances"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "scheduled_maintenances"."slug" IS 'Public URL segment.';
COMMENT ON COLUMN "scheduled_maintenances"."title" IS 'What is being done, in customer terms.';
COMMENT ON COLUMN "scheduled_maintenances"."description" IS 'Expected impact in detail, published when the window is announced rather than when it starts.';
COMMENT ON COLUMN "scheduled_maintenances"."status" IS 'scheduled | in_progress | completed | cancelled. Cancelled windows stay as rows because subscribers were already notified and are owed the retraction.';
COMMENT ON COLUMN "scheduled_maintenances"."scheduled_start_at" IS 'Announced start. Subscribers are notified relative to this, so moving it is a communication event, not an edit.';
COMMENT ON COLUMN "scheduled_maintenances"."scheduled_end_at" IS 'Announced end. Customers plan around this number more than any other on the page.';
COMMENT ON COLUMN "scheduled_maintenances"."actual_start_at" IS 'When work really began. Null until it does.';
COMMENT ON COLUMN "scheduled_maintenances"."actual_end_at" IS 'When it really finished. Overrunning a window is the complaint maintenance generates, and it is only visible if planned and actual are both kept.';
COMMENT ON COLUMN "scheduled_maintenances"."notify_hours_before" IS 'Lead time for the reminder notification. Per window, because a five-minute restart and a four-hour migration deserve different warning.';
COMMENT ON COLUMN "scheduled_maintenances"."auto_transition" IS 'Whether status moves on the schedule without a human. Convenient and dangerous: an automatic completion while work is still running publishes a lie.';

CREATE INDEX "idx_maintenances_scheduled_start"
ON "scheduled_maintenances" ("scheduled_start_at");
CREATE INDEX "idx_maintenances_status"
ON "scheduled_maintenances" ("status");

CREATE TABLE IF NOT EXISTS "maintenance_components" (
	-- Maintenance window. Half of the composite key.
	"maintenance_id" BIGINT,
	-- Component affected. Half of the composite key.
	"component_id" BIGINT,
	-- under_maintenance | degraded_performance | major_outage. Some maintenance is genuinely invisible and some takes the service down; saying which in advance is the whole point of announcing it.
	"expected_impact" VARCHAR(24) NOT NULL DEFAULT 'under_maintenance',
	PRIMARY KEY("maintenance_id", "component_id")
);

COMMENT ON TABLE "maintenance_components" IS 'Scope of a maintenance window. Separate from incident scope because the impact vocabulary and the uptime treatment differ.';
COMMENT ON COLUMN "maintenance_components"."maintenance_id" IS 'Maintenance window. Half of the composite key.';
COMMENT ON COLUMN "maintenance_components"."component_id" IS 'Component affected. Half of the composite key.';
COMMENT ON COLUMN "maintenance_components"."expected_impact" IS 'under_maintenance | degraded_performance | major_outage. Some maintenance is genuinely invisible and some takes the service down; saying which in advance is the whole point of announcing it.';

CREATE INDEX "idx_maintenance_components_component"
ON "maintenance_components" ("component_id");

CREATE TABLE IF NOT EXISTS "status_updates" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Incident this update belongs to. Exactly one of incident_id and maintenance_id is set, enforced by a check constraint.
	"incident_id" BIGINT,
	-- Maintenance window this update belongs to. Null for incident updates.
	"maintenance_id" BIGINT,
	-- investigating | identified | monitoring | resolved | scheduled | in_progress | completed. The state the parent moved into with this post, so the timeline explains itself without joining back.
	"update_status" VARCHAR(24) NOT NULL,
	-- What is published, verbatim. Never derived from a template at render time, because a message shown to customers must be reproducible exactly as it was sent.
	"body" TEXT NOT NULL,
	-- Publication time. The ordering key of the public timeline, which is the most-read artefact of the entire system.
	"posted_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	-- Author, shown internally and usually not publicly.
	"posted_by" VARCHAR(120),
	-- Whether this post generates notifications. False for a typo fix, which must not wake ten thousand people a second time.
	"notify_subscribers" BOOLEAN NOT NULL DEFAULT true,
	-- False for an internal note kept on the same timeline, so responders are not maintaining two chronologies during an incident.
	"is_public" BOOLEAN NOT NULL DEFAULT true,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "status_updates" IS 'The public timeline, append-only. Updates are never edited in place: a correction is a new post, because the previous one has already been emailed, syndicated and screenshotted.';
COMMENT ON COLUMN "status_updates"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "status_updates"."incident_id" IS 'Incident this update belongs to. Exactly one of incident_id and maintenance_id is set, enforced by a check constraint.';
COMMENT ON COLUMN "status_updates"."maintenance_id" IS 'Maintenance window this update belongs to. Null for incident updates.';
COMMENT ON COLUMN "status_updates"."update_status" IS 'investigating | identified | monitoring | resolved | scheduled | in_progress | completed. The state the parent moved into with this post, so the timeline explains itself without joining back.';
COMMENT ON COLUMN "status_updates"."body" IS 'What is published, verbatim. Never derived from a template at render time, because a message shown to customers must be reproducible exactly as it was sent.';
COMMENT ON COLUMN "status_updates"."posted_at" IS 'Publication time. The ordering key of the public timeline, which is the most-read artefact of the entire system.';
COMMENT ON COLUMN "status_updates"."posted_by" IS 'Author, shown internally and usually not publicly.';
COMMENT ON COLUMN "status_updates"."notify_subscribers" IS 'Whether this post generates notifications. False for a typo fix, which must not wake ten thousand people a second time.';
COMMENT ON COLUMN "status_updates"."is_public" IS 'False for an internal note kept on the same timeline, so responders are not maintaining two chronologies during an incident.';

CREATE INDEX "idx_updates_incident_time"
ON "status_updates" ("incident_id", "posted_at");
CREATE INDEX "idx_updates_maintenance_time"
ON "status_updates" ("maintenance_id", "posted_at");

CREATE TABLE IF NOT EXISTS "postmortems" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Incident being reviewed. Unique, so one incident has at most one postmortem and the write-up cannot quietly fork.
	"incident_id" BIGINT NOT NULL UNIQUE,
	-- Publication time. Null while in draft, which is where most postmortems live for a week.
	"published_at" TIMESTAMPTZ,
	-- What happened, in the customer language of the incident rather than the internal language of the fix.
	"summary" TEXT NOT NULL,
	-- Why it happened. Nullable because publishing on time with an honest unknown beats publishing late with a guess.
	"root_cause" TEXT,
	-- What restored service, which is frequently not the same as what prevents a recurrence.
	"resolution" TEXT,
	-- Follow-up commitments with owners and dates, as a document. Schemaless because the real tracking lives in an issue tracker and this is the published snapshot of it.
	"action_items" JSONB,
	-- Defaults to false so a draft cannot be published by existing. Making it public is a deliberate act.
	"is_public" BOOLEAN NOT NULL DEFAULT false,
	PRIMARY KEY("id")
);

COMMENT ON TABLE "postmortems" IS 'The retrospective, separate from the incident because it is written days later, reviewed, and often published under different rules than the live updates were.';
COMMENT ON COLUMN "postmortems"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "postmortems"."incident_id" IS 'Incident being reviewed. Unique, so one incident has at most one postmortem and the write-up cannot quietly fork.';
COMMENT ON COLUMN "postmortems"."published_at" IS 'Publication time. Null while in draft, which is where most postmortems live for a week.';
COMMENT ON COLUMN "postmortems"."summary" IS 'What happened, in the customer language of the incident rather than the internal language of the fix.';
COMMENT ON COLUMN "postmortems"."root_cause" IS 'Why it happened. Nullable because publishing on time with an honest unknown beats publishing late with a guess.';
COMMENT ON COLUMN "postmortems"."resolution" IS 'What restored service, which is frequently not the same as what prevents a recurrence.';
COMMENT ON COLUMN "postmortems"."action_items" IS 'Follow-up commitments with owners and dates, as a document. Schemaless because the real tracking lives in an issue tracker and this is the published snapshot of it.';
COMMENT ON COLUMN "postmortems"."is_public" IS 'Defaults to false so a draft cannot be published by existing. Making it public is a deliberate act.';

CREATE TABLE IF NOT EXISTS "subscribers" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- email | webhook | sms | slack. The channel decides the delivery mechanism, the retry policy and what counts as a permanent failure.
	"channel" VARCHAR(16) NOT NULL DEFAULT 'email',
	-- Email address, webhook URL or channel identifier. One column because the semantics are identical — somewhere to send a payload — and three nullable columns would only move the validation elsewhere.
	"address" VARCHAR(500) NOT NULL,
	-- When ownership was confirmed. Null means unverified, and sending to an unverified address is how a status page becomes a spam vector for someone else.
	"verified_at" TIMESTAMPTZ,
	-- Opaque token in the unsubscribe link. Unique and unguessable, so one-click unsubscribe works without a login and cannot be used to remove somebody else.
	"unsubscribe_token" VARCHAR(64) NOT NULL UNIQUE,
	-- pending | active | unsubscribed | bounced. Bounced is set by the delivery pipeline, not by the subscriber, and stops sending without losing the record.
	"status" VARCHAR(16) NOT NULL DEFAULT 'pending',
	-- Preferred language tag for notifications, e.g. en-GB or ja-JP.
	"locale" VARCHAR(12),
	-- Subscription time.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "subscribers" IS 'Someone who wants to be told. Email and webhook subscribers share a table because everything downstream — selection, templating, retry, suppression — is identical once the payload is built.';
COMMENT ON COLUMN "subscribers"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "subscribers"."channel" IS 'email | webhook | sms | slack. The channel decides the delivery mechanism, the retry policy and what counts as a permanent failure.';
COMMENT ON COLUMN "subscribers"."address" IS 'Email address, webhook URL or channel identifier. One column because the semantics are identical — somewhere to send a payload — and three nullable columns would only move the validation elsewhere.';
COMMENT ON COLUMN "subscribers"."verified_at" IS 'When ownership was confirmed. Null means unverified, and sending to an unverified address is how a status page becomes a spam vector for someone else.';
COMMENT ON COLUMN "subscribers"."unsubscribe_token" IS 'Opaque token in the unsubscribe link. Unique and unguessable, so one-click unsubscribe works without a login and cannot be used to remove somebody else.';
COMMENT ON COLUMN "subscribers"."status" IS 'pending | active | unsubscribed | bounced. Bounced is set by the delivery pipeline, not by the subscriber, and stops sending without losing the record.';
COMMENT ON COLUMN "subscribers"."locale" IS 'Preferred language tag for notifications, e.g. en-GB or ja-JP.';
COMMENT ON COLUMN "subscribers"."created_at" IS 'Subscription time.';

CREATE UNIQUE INDEX "uq_subscribers_channel_address"
ON "subscribers" ("channel", "address");
CREATE INDEX "idx_subscribers_status"
ON "subscribers" ("status");

CREATE TABLE IF NOT EXISTS "subscriber_components" (
	-- Subscriber. Half of the composite key.
	"subscriber_id" BIGINT,
	-- Component they want updates about. Half of the composite key.
	"component_id" BIGINT,
	-- When this preference was set.
	"created_at" TIMESTAMPTZ NOT NULL DEFAULT now(),
	PRIMARY KEY("subscriber_id", "component_id")
);

COMMENT ON TABLE "subscriber_components" IS 'Per-component subscription preferences. No rows for a subscriber means everything, which keeps the common case free of writes and makes the selective case explicit rather than inferred.';
COMMENT ON COLUMN "subscriber_components"."subscriber_id" IS 'Subscriber. Half of the composite key.';
COMMENT ON COLUMN "subscriber_components"."component_id" IS 'Component they want updates about. Half of the composite key.';
COMMENT ON COLUMN "subscriber_components"."created_at" IS 'When this preference was set.';

CREATE TABLE IF NOT EXISTS "notification_deliveries" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Update being delivered. Deliveries are per update, not per incident, because each post is its own send.
	"status_update_id" BIGINT NOT NULL,
	-- Recipient.
	"subscriber_id" BIGINT NOT NULL,
	-- Channel used, copied from the subscriber so a later channel change does not rewrite delivery history.
	"channel" VARCHAR(16) NOT NULL,
	-- queued | sent | delivered | failed | bounced | suppressed. Suppressed covers a deliberate skip — unverified, unsubscribed mid-send, or rate limited — and is not a failure.
	"status" VARCHAR(16) NOT NULL DEFAULT 'queued',
	-- Retries so far. Webhooks need several with backoff; email is usually one attempt and a bounce.
	"attempt_count" SMALLINT NOT NULL DEFAULT 0,
	-- Most recent try, which drives the backoff schedule.
	"last_attempt_at" TIMESTAMPTZ,
	-- Confirmed acceptance by the provider or a 2xx from the webhook endpoint.
	"delivered_at" TIMESTAMPTZ,
	-- Identifier from the email or SMS provider. The join key when a bounce webhook arrives hours later.
	"provider_message_id" VARCHAR(160),
	-- Last failure reason, kept so a customer asking why they were not notified gets an answer rather than a shrug.
	"error_detail" VARCHAR(500),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "notification_deliveries" IS 'One row per update per recipient. The unique constraint is the idempotency guarantee: a notification job that crashes halfway and restarts cannot send the same incident update twice.';
COMMENT ON COLUMN "notification_deliveries"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "notification_deliveries"."status_update_id" IS 'Update being delivered. Deliveries are per update, not per incident, because each post is its own send.';
COMMENT ON COLUMN "notification_deliveries"."subscriber_id" IS 'Recipient.';
COMMENT ON COLUMN "notification_deliveries"."channel" IS 'Channel used, copied from the subscriber so a later channel change does not rewrite delivery history.';
COMMENT ON COLUMN "notification_deliveries"."status" IS 'queued | sent | delivered | failed | bounced | suppressed. Suppressed covers a deliberate skip — unverified, unsubscribed mid-send, or rate limited — and is not a failure.';
COMMENT ON COLUMN "notification_deliveries"."attempt_count" IS 'Retries so far. Webhooks need several with backoff; email is usually one attempt and a bounce.';
COMMENT ON COLUMN "notification_deliveries"."last_attempt_at" IS 'Most recent try, which drives the backoff schedule.';
COMMENT ON COLUMN "notification_deliveries"."delivered_at" IS 'Confirmed acceptance by the provider or a 2xx from the webhook endpoint.';
COMMENT ON COLUMN "notification_deliveries"."provider_message_id" IS 'Identifier from the email or SMS provider. The join key when a bounce webhook arrives hours later.';
COMMENT ON COLUMN "notification_deliveries"."error_detail" IS 'Last failure reason, kept so a customer asking why they were not notified gets an answer rather than a shrug.';

CREATE UNIQUE INDEX "uq_deliveries_update_subscriber"
ON "notification_deliveries" ("status_update_id", "subscriber_id");
CREATE INDEX "idx_deliveries_status"
ON "notification_deliveries" ("status");

CREATE TABLE IF NOT EXISTS "uptime_samples" (
	-- Surrogate primary key.
	"id" BIGINT GENERATED BY DEFAULT AS IDENTITY,
	-- Component probed.
	"component_id" BIGINT NOT NULL,
	-- When the probe ran. Retained for a short window only; the daily rollup is what survives.
	"checked_at" TIMESTAMPTZ NOT NULL,
	-- Whether the check passed. A single boolean, because a status page that publishes a nuanced health score nobody can interpret has failed at its job.
	"is_up" BOOLEAN NOT NULL,
	-- Response time. Null on a timeout, which is different from a fast failure and must not be recorded as zero.
	"latency_ms" INTEGER,
	-- Status code returned, for diagnosing a check that fails for an uninteresting reason.
	"http_status" SMALLINT,
	-- Where the probe ran from. Two of five regions failing is a network problem, not an outage, and without this column the two are indistinguishable.
	"region" VARCHAR(32),
	-- Failure detail from the prober.
	"error_detail" VARCHAR(300),
	PRIMARY KEY("id")
);

COMMENT ON TABLE "uptime_samples" IS 'Raw health checks, kept briefly. They are evidence for the status history rather than the source of the public page — a single failed probe is noise, and promoting it straight to an outage is how a status page loses credibility.';
COMMENT ON COLUMN "uptime_samples"."id" IS 'Surrogate primary key.';
COMMENT ON COLUMN "uptime_samples"."component_id" IS 'Component probed.';
COMMENT ON COLUMN "uptime_samples"."checked_at" IS 'When the probe ran. Retained for a short window only; the daily rollup is what survives.';
COMMENT ON COLUMN "uptime_samples"."is_up" IS 'Whether the check passed. A single boolean, because a status page that publishes a nuanced health score nobody can interpret has failed at its job.';
COMMENT ON COLUMN "uptime_samples"."latency_ms" IS 'Response time. Null on a timeout, which is different from a fast failure and must not be recorded as zero.';
COMMENT ON COLUMN "uptime_samples"."http_status" IS 'Status code returned, for diagnosing a check that fails for an uninteresting reason.';
COMMENT ON COLUMN "uptime_samples"."region" IS 'Where the probe ran from. Two of five regions failing is a network problem, not an outage, and without this column the two are indistinguishable.';
COMMENT ON COLUMN "uptime_samples"."error_detail" IS 'Failure detail from the prober.';

CREATE INDEX "idx_samples_component_time"
ON "uptime_samples" ("component_id", "checked_at");

CREATE TABLE IF NOT EXISTS "uptime_daily" (
	-- Component. Half of the composite key.
	"component_id" BIGINT,
	-- Calendar day in the page display timezone. Half of the composite key. A date rather than a timestamp, because the uptime bar has one cell per day and that cell is a local-day fact.
	"day" DATE,
	-- Seconds fully operational.
	"up_seconds" INTEGER NOT NULL DEFAULT 0,
	-- Seconds degraded. Counted separately so a policy that treats degradation as partial downtime can be changed without recomputing from raw samples.
	"degraded_seconds" INTEGER NOT NULL DEFAULT 0,
	-- Seconds in partial or major outage.
	"down_seconds" INTEGER NOT NULL DEFAULT 0,
	-- Seconds in announced maintenance. Kept apart because most published uptime figures exclude it, and that exclusion must be visible rather than silently baked into the percentage.
	"maintenance_seconds" INTEGER NOT NULL DEFAULT 0,
	-- Published percentage for the day, four decimals so the difference between 99.99 and 99.9999 survives. Stored rather than computed, because the formula changes and history must not.
	"uptime_pct" NUMERIC(6,4) NOT NULL DEFAULT 100,
	-- Probes behind the figure. A day with four samples does not deserve four decimal places, and this is what lets the page say so.
	"sample_count" INTEGER NOT NULL DEFAULT 0,
	PRIMARY KEY("component_id", "day")
);

COMMENT ON TABLE "uptime_daily" IS 'Daily rollup derived from component_status_history and the samples. Published uptime is a computed, policy-laden number — which statuses count, whether maintenance is excluded — so the inputs are stored beside the result and the result is frozen.';
COMMENT ON COLUMN "uptime_daily"."component_id" IS 'Component. Half of the composite key.';
COMMENT ON COLUMN "uptime_daily"."day" IS 'Calendar day in the page display timezone. Half of the composite key. A date rather than a timestamp, because the uptime bar has one cell per day and that cell is a local-day fact.';
COMMENT ON COLUMN "uptime_daily"."up_seconds" IS 'Seconds fully operational.';
COMMENT ON COLUMN "uptime_daily"."degraded_seconds" IS 'Seconds degraded. Counted separately so a policy that treats degradation as partial downtime can be changed without recomputing from raw samples.';
COMMENT ON COLUMN "uptime_daily"."down_seconds" IS 'Seconds in partial or major outage.';
COMMENT ON COLUMN "uptime_daily"."maintenance_seconds" IS 'Seconds in announced maintenance. Kept apart because most published uptime figures exclude it, and that exclusion must be visible rather than silently baked into the percentage.';
COMMENT ON COLUMN "uptime_daily"."uptime_pct" IS 'Published percentage for the day, four decimals so the difference between 99.99 and 99.9999 survives. Stored rather than computed, because the formula changes and history must not.';
COMMENT ON COLUMN "uptime_daily"."sample_count" IS 'Probes behind the figure. A day with four samples does not deserve four decimal places, and this is what lets the page say so.';

CREATE INDEX "idx_uptime_daily_day"
ON "uptime_daily" ("day");

